<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();$pageTitle='Reports & Analytics';
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
$s=$pdo->prepare("SELECT COUNT(*) transactions,COALESCE(SUM(total_amount),0) sales,COALESCE(SUM(discount),0) discounts FROM sales WHERE status='completed' AND DATE(sold_at) BETWEEN ? AND ?");$s->execute([$from,$to]);$summary=$s->fetch();
$e=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE expense_date BETWEEN ? AND ?');$e->execute([$from,$to]);$expenseTotal=(float)$e->fetchColumn();
$c=$pdo->prepare("SELECT COALESCE(SUM((si.unit_price-si.unit_cost)*si.quantity),0) FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.status='completed' AND DATE(s.sold_at) BETWEEN ? AND ?");$c->execute([$from,$to]);$grossProfit=(float)$c->fetchColumn();
$top=$pdo->prepare("SELECT si.product_name,SUM(si.quantity) qty,SUM(si.subtotal) revenue FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.status='completed' AND DATE(s.sold_at) BETWEEN ? AND ? GROUP BY si.product_id,si.product_name ORDER BY qty DESC LIMIT 10");$top->execute([$from,$to]);$topProducts=$top->fetchAll();
$daily=$pdo->prepare("SELECT DATE(sold_at) day,SUM(total_amount) total FROM sales WHERE status='completed' AND DATE(sold_at) BETWEEN ? AND ? GROUP BY DATE(sold_at) ORDER BY day");$daily->execute([$from,$to]);$dailyRows=$daily->fetchAll();
$stock=$pdo->query('SELECT p.name,p.stock_qty,p.unit,p.cost_price,p.selling_price,p.min_stock,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.active=1 ORDER BY p.name')->fetchAll();
require __DIR__.'/includes/header.php';
?>
<div class="panel"><div class="panel-heading"><div><h3>Business performance</h3><p>Choose a period to calculate sales and profit estimates.</p></div></div><form class="filter-bar" method="get"><label>From <input type="date" name="from" value="<?= e($from) ?>" required></label><label>To <input type="date" name="to" value="<?= e($to) ?>" required></label><button class="btn primary">Generate report</button><a class="btn secondary" href="reports.php?from=<?= date('Y-m-01') ?>&to=<?= date('Y-m-d') ?>">This month</a></form></div>
<div class="stats-grid"><article class="stat-card"><span class="muted">Completed sales</span><strong><?= money($summary['sales']) ?></strong><small><?= (int)$summary['transactions'] ?> transactions</small></article><article class="stat-card"><span class="muted">Estimated gross profit</span><strong><?= money($grossProfit) ?></strong><small>Before expenses and other costs</small></article><article class="stat-card"><span class="muted">Recorded expenses</span><strong><?= money($expenseTotal) ?></strong><small>Expenses entered for this period</small></article><article class="stat-card"><span class="muted">Estimated net after expenses</span><strong><?= money($grossProfit-$expenseTotal) ?></strong><small>Estimate based on recorded data</small></article></div>
<div class="dashboard-grid"><article class="panel chart-panel"><div class="panel-heading"><div><h3>Daily sales</h3><p>Completed sales by transaction date</p></div></div><div class="chart-wrap"><canvas id="reportChart"></canvas></div></article><article class="panel"><div class="panel-heading"><div><h3>Top-selling products</h3><p>Ranked by quantity sold</p></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Qty sold</th><th class="align-right">Revenue</th></tr></thead><tbody><?php foreach($topProducts as $p): ?><tr><td><?= e($p['product_name']) ?></td><td><?= e((string)$p['qty']) ?></td><td class="align-right"><?= money($p['revenue']) ?></td></tr><?php endforeach; ?><?php if(!$topProducts): ?><tr><td colspan="3">No sales for this period.</td></tr><?php endif; ?></tbody></table></div></article></div>
<div class="panel"><div class="panel-heading"><div><h3>Inventory valuation</h3><p>Current active stock, valued at recorded cost.</p></div><button class="btn secondary" onclick="window.print()">Print report</button></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Stock</th><th>Cost</th><th>Selling price</th><th class="align-right">Stock value</th></tr></thead><tbody><?php $inventoryTotal=0;foreach($stock as $p):$value=(float)$p['stock_qty']*(float)$p['cost_price'];$inventoryTotal+=$value; ?><tr><td><?= e($p['name']) ?></td><td><?= e($p['category']??'Uncategorized') ?></td><td><?= e((string)$p['stock_qty']) ?> <?= e($p['unit']) ?><?php if((float)$p['stock_qty']<=(float)$p['min_stock']): ?> <span class="badge warning">Low</span><?php endif; ?></td><td><?= money($p['cost_price']) ?></td><td><?= money($p['selling_price']) ?></td><td class="align-right"><?= money($value) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><th colspan="5">Total current inventory value</th><th class="align-right"><?= money($inventoryTotal) ?></th></tr></tfoot></table></div></div>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>document.addEventListener('DOMContentLoaded',()=>{const el=document.getElementById('reportChart');if(!el||!window.Chart)return;new Chart(el,{type:'bar',data:{labels:<?= json_encode(array_map(fn($r)=>date('M j',strtotime($r['day'])),$dailyRows)) ?>,datasets:[{label:'Sales',data:<?= json_encode(array_map(fn($r)=>(float)$r['total'],$dailyRows)) ?>,backgroundColor:'#df794e',borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{callback:v=>'₱'+v}},x:{grid:{display:false}}}}});});</script>
<?php require __DIR__.'/includes/footer.php'; ?>
